	// SearchParameter: onset-date (date)
	// FHIRPath: Condition.onset.as(dateTime) | Condition.onset.as(Period)
	// Choice type: onset as dateTime
	if d := r.GetOnset(); d != nil {
		if dt := d.GetDateTime(); dt != nil {
			t := time.UnixMicro(dt.GetValueUs()).UTC()
			idx.Dates = append(idx.Dates, SpidxDate{
				TenantID: tenantID,
				ResType:  "Condition",
				ResID:    resID,
				SpName:   "onset-date",
				SpLow:    t,
				SpHigh:   t,
			})
		}
		if p := d.GetPeriod(); p != nil {
			var low, high time.Time
			if p.GetStart() != nil {
				low = time.UnixMicro(p.GetStart().GetValueUs()).UTC()
			}
			if p.GetEnd() != nil {
				high = time.UnixMicro(p.GetEnd().GetValueUs()).UTC()
			}
			if !low.IsZero() || !high.IsZero() {
				if low.IsZero() {
					low = high
				}
				if high.IsZero() {
					high = low
				}
				idx.Dates = append(idx.Dates, SpidxDate{
					TenantID: tenantID,
					ResType:  "Condition",
					ResID:    resID,
					SpName:   "onset-date",
					SpLow:    low,
					SpHigh:   high,
				})
			}
		}
	}

